#include "seed/config.hpp"
#include "seed/database.hpp"
#include "seed/engine.hpp"
#include "seed/protocol.hpp"
#include "seed/socket.hpp"
#include "seed/ui.hpp"
#include <iostream>
int main(int argc,char**argv){try{seed::boot_loader();auto c=seed::Config::load(argc>1?argv[1]:"config/seed.ini");seed::loading_screen("Initializing database");seed::Database db(c);if(!db.connect()){std::cerr<<"Database connection failed; check MySQL and config.\n";return 2;}std::string e;if(!db.initialize_schema(&e)){std::cerr<<e<<"\n";return 3;}if(!db.bootstrap_admin_from_environment(&e)){std::cerr<<e<<"\n";return 4;}std::cout<<"Storage: "<<(db.mysql_enabled()?"MySQL":"in-memory development mode")<<"\n";auto h=[&](const std::string&line){auto f=seed::split_tabs(line);if(f.empty())return seed::response(false,"empty command");if(f[0]=="PING")return seed::response(true,"pong");if(f[0]=="REGISTER"&&f.size()==3){std::string e;bool ok=db.register_user(f[1],f[2],&e);return seed::response(ok,ok?"registered":e);}if(f[0]=="LOGIN"&&f.size()==3){auto u=db.authenticate(f[1],f[2]);if(!u)return seed::response(false,"invalid credentials or disabled user");return seed::response(true,"user="+u->username+";role="+seed::role_name(u->role));}if(f[0]=="LOGOUT")return seed::response(true,"client logout acknowledged");if(f[0]=="WORLD"&&f.size()==3){try{auto n=std::stoull(f[2]);if(n>1000)return seed::response(false,"max planets is 1000");auto w=seed::MathEngine::generate_demo_world(std::stoull(f[1]),n);return seed::response(true,"seed="+std::to_string(w.seed)+";planets="+std::to_string(w.planets.size()));}catch(...){return seed::response(false,"invalid seed/count");}}if(f[0].rfind("ADMIN_",0)==0)return seed::response(false,"network admin commands disabled until authenticated server sessions are implemented");return seed::response(false,"unknown command");};return seed::run_tcp_server(c.host,c.port,c.max_clients,h)?0:5;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
